import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('noteedit_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const kinds=['duplicate','quantize','quantize-pitch','select-ids','select-all','select-none','delete-range'];
function setup(sim){const clip=sim.state.tracks[0].clips[0];clip.notes[0].start=0.11;clip.notes.push({...structuredClone(clip.notes[0]),id:2,start:0.9,pitch:40});}
function params(kind){return {clipRef:'clip:clip-1',...(kind==='duplicate'?{action:'duplicate',noteIds:[1,2]}:kind.startsWith('select-')?{action:'select',...(kind==='select-ids'?{noteIds:[1]}:kind==='select-all'?{all:true}:{none:true})}:kind==='delete-range'?{action:kind,fromPitch:36,pitchSpan:1,fromTime:0,timeSpan:0.5}:{action:kind,grid:0.5,amount:0.7,...(kind==='quantize-pitch'?{pitch:36}:{})})};}
const rows=[];for(const kind of kinds)for(const action of ['preview','apply']){const valid=action==='preview'?params(kind):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true},...[[1,1],[1,2],[1.0],[1,3],[-1],[1.5],[null],['1'],[true],[1e308],Array.from({length:4097},(_,i)=>i)].map(noteIds=>({...valid,noteIds}))];for(const key of (action==='preview'?['clipRef','action','noteIds','grid','amount','pitch','all','none','fromPitch','pitchSpan','fromTime','timeSpan']:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.000999,0.001,0.5,1,127,128,129,1e9,1e9+1,100001,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const sim=new DeterministicLiveSimulator();setup(sim,'session-midi');const host=new McpHost(sim);let result;try{result=clean(await host[action==='preview'?'liveNoteTargetPreviewAsync':'liveNoteTargetApplyAsync'](1,args));}catch(e){result={error:e.message};}rows.push({action,args,result});}}
const workflows=[];for(const kind of kinds)for(const scenario of ['normal','expire','epoch','identity-edit','source-content','note-edit','revision-edit','missing-optionals','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','apply-count','apply-identity','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-epoch']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();setup(sim,kind);let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')delete sim.state.tracks[0].clips[0].objectIdentity;if(scenario==='missing-optionals')for(const n of sim.state.tracks[0].clips[0].notes)for(const f of ['mute','probability','velocityDeviation','releaseVelocity'])delete n[f];
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';}if(!fired&&fault==='apply-count'){fired=true;for(const field of ['duplicated','selected','deleted'])if(field in result)result[field]++;result.changed=false;}if(!fired&&fault==='apply-identity'){fired=true;const note=sim.state.tracks[0].clips[0].notes[0];if(note)note.id=100;}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const args=params(kind);const preview=await host.liveNoteTargetPreviewAsync(1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveNoteTargetApplyAsync(results.length+1,args,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.tracks[0].clips[0].objectIdentity='other';if(scenario==='source-content')sim.state.tracks[0].clips[0].name='Manual';if(scenario==='note-edit')sim.state.tracks[0].clips[0].notes[0].velocity=60;if(scenario==='revision-edit')sim.state.tracks[0].clips[0].notesRevision='manual';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')sim.state.tracks[0].clips[0].objectIdentity='other';if(scenario==='undo-other-content')sim.state.tracks[0].clips[0].notes.push({id:100,pitch:80,start:2,duration:1,velocity:90,channel:1});if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-note-target-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
